    const texts = ['첫째 요약입니다.', '둘째 요약입니다.', '셋째 요약입니다.', '넷째 요약입니다.'];
    for (const [index, text] of texts.entries()) await seedSummary(chatId, ids.slice(index * 2, index * 2 + 2), text, index === 0);
    // Room for one summary only, its time label included.
