    expect(await claimOf(chatId)).toBeNull();
    const kept = (await rowsOf(chatId)).at(-1)!;
    expect(kept).toMatchObject({ content: '반쯤', speakerMemberId: kai, groupTurnId: a.messageId, parentId: a.messageId });
